class Solution {
public:
    string subStrHash(string s, int power, int modulo, int k, int hashValue) {
        long long hash = 0, factor = 1;
        for (int i = 0; i < k; ++i) factor = factor * power % modulo;
        int ans = 0;
        for (int i = (int)s.size() - 1; i >= 0; --i) {
            hash = (hash * power + (s[i] - 'a' + 1)) % modulo;
            if (i + k < (int)s.size()) {
                hash = (hash - factor * (s[i + k] - 'a' + 1) % modulo + modulo) % modulo;
            }
            if (i + k <= (int)s.size() && hash == hashValue) ans = i;
        }
        return s.substr(ans, k);
    }
};
